use mathlab_language::program::*;
use std::future::Future;
#[derive(Default)]struct Control{units:u64,reserves:usize,bytes:usize,fail:Option<usize>,stop:Option<usize>,checkpoints:usize}
impl ScientificControlV1 for Control{fn charge(&mut self,n:u64)->Result<(),ScientificErrorV1>{assert!(n<=128);self.checkpoints+=1;if self.stop==Some(self.checkpoints){return Err(ScientificErrorV1::Cancelled)}self.units+=n;Ok(())}fn reserve(&mut self,n:usize)->Result<(),ScientificErrorV1>{self.reserves+=1;if self.fail==Some(self.reserves){return Err(ScientificErrorV1::Allocation)}self.bytes+=n;Ok(())}}
fn drive<T>(f:impl Future<Output=T>)->T{let mut f=std::pin::pin!(f);let mut cx=std::task::Context::from_waker(std::task::Waker::noop());loop{if let std::task::Poll::Ready(v)=f.as_mut().poll(&mut cx){return v}}}
fn real(shape:&[u64],x:&[f64])->ScientificProgramValueV2{ScientificProgramValueV2::from_dense(drive(ScientificDenseV1::from_real_cooperative(ScientificShapeV1::new(shape).unwrap(),x,&mut Control::default())).unwrap())}
fn complex(shape:&[u64],x:&[Complex64V1])->ScientificProgramValueV2{ScientificProgramValueV2::from_dense(drive(ScientificDenseV1::from_complex_cooperative(ScientificShapeV1::new(shape).unwrap(),x,&mut Control::default())).unwrap())}
fn sparse(i:&ScientificProgramValueV2,j:&ScientificProgramValueV2,v:&ScientificProgramValueV2,m:u64,n:u64,c:&mut Control)->Result<ScientificProgramValueV2,ScientificErrorV1>{drive(construct_scientific_sparse_v2(i,j,v,ScientificCscShapeV1::new(m,n).unwrap(),64<<20,c))}
#[test]fn typed_storage_scalar_expansion_empty_and_final_class(){
 let i=real(&[1,1],&[1.]);let j=real(&[3,1],&[1.,2.,3.]);let v=real(&[3,1],&[2.,3.,4.]);let a=sparse(&i,&j,&v,2,3,&mut Control::default()).unwrap();assert!(a.is_sparse());assert_eq!(&*a.axes(),[2,3]);assert_eq!(a.logical_numel(),6);assert!(a.dense_view().is_err());assert_eq!(a.csc_view().unwrap().column_pointers(),[0,1,2,3]);assert_eq!(a.csc_view().unwrap().row_indices(),[0,0,0]);
 let empty=real(&[0,0],&[]);let nan=complex(&[1,1],&[Complex64V1{re:f64::NAN,im:7.}]);for args in [(&empty,&i,&nan),(&i,&empty,&nan),(&i,&i,&empty),(&empty,&empty,&nan)]{let a=sparse(args.0,args.1,args.2,2,3,&mut Control::default()).unwrap();assert!(a.is_empty()==false);assert_eq!(a.stored_len(),0);assert!(!a.is_complex());assert_eq!(a.csc_view().unwrap().nzmax(),1);assert_eq!(a.payload_bytes(),28)}
 let i=real(&[3,1],&[1.,1.,1.]);let j=real(&[1,1],&[1.]);let v=real(&[3,1],&[1e16,-1e16,6.]);let a=sparse(&i,&j,&v,1,1,&mut Control::default()).unwrap();assert_eq!(a.scalar().unwrap(),6.);
}
#[test]fn native_nonfinite_structure_and_component_paths(){
 let index=real(&[1,1],&[1.]);let empty=real(&[0,0],&[]);let zero=sparse(&empty,&empty,&empty,2,2,&mut Control::default()).unwrap();let rhs=real(&[2,1],&[f64::INFINITY,1.]);let z=drive(multiply_sparse_dense_ieee_v2(zero.csc_view().unwrap(),rhs.dense_view().unwrap(),64<<20,&mut Control::default())).unwrap();assert_eq!(z.dense_component(0).unwrap().re,0.);assert_eq!(z.dense_component(1).unwrap().re,0.);
 for (value,rhs,expected,imag)in [(Complex64V1{re:2.,im:3.},f64::INFINITY,f64::INFINITY,f64::INFINITY),(Complex64V1{re:f64::INFINITY,im:1.},0.,f64::NAN,0.)]{let v=complex(&[1,1],&[value]);let a=sparse(&index,&index,&v,2,2,&mut Control::default()).unwrap();let b=real(&[2,1],&[rhs,1.]);let y=drive(multiply_sparse_dense_ieee_v2(a.csc_view().unwrap(),b.dense_view().unwrap(),64<<20,&mut Control::default())).unwrap();let z=y.dense_component(0).unwrap();if expected.is_nan(){assert!(z.re.is_nan());assert!(!y.is_complex())}else{assert_eq!(z.re,expected);assert!(y.is_complex())}assert_eq!(z.im,imag);assert_eq!(y.dense_component(1).unwrap(),Complex64V1::ZERO)}
 let a=sparse(&index,&index,&real(&[1,1],&[f64::INFINITY]),1,1,&mut Control::default()).unwrap();let b=complex(&[1,1],&[Complex64V1{re:1.,im:0.}]);let y=drive(multiply_sparse_dense_ieee_v2(a.csc_view().unwrap(),b.dense_view().unwrap(),64<<20,&mut Control::default())).unwrap();assert!(y.is_sparse());assert!(!y.is_complex());assert_eq!(y.scalar().unwrap(),f64::INFINITY);
}
#[test]fn sparse_nan_truth_checks_stored_entries_before_implicit_false(){let i=real(&[1,1],&[1.]);let v=real(&[1,1],&[f64::NAN]);let a=sparse(&i,&i,&v,2,2,&mut Control::default()).unwrap();assert_eq!(drive(scientific_truth_v2(&a,&mut Control::default())),Err(ScientificErrorV1::Type));let copy=drive(a.try_copy_cooperative(64<<20,&mut Control::default())).unwrap();assert_eq!(drive(scientific_truth_v2(&copy,&mut Control::default())),Err(ScientificErrorV1::Type));}
#[test]fn constructor_reserve_faults_and_every_checkpoint_stop_are_recoverable(){
 let i=real(&[4,1],&[2.,1.,2.,1.]);let j=real(&[4,1],&[2.,1.,2.,2.]);let v=real(&[4,1],&[3.,4.,5.,6.]);let mut baseline=Control::default();let a=sparse(&i,&j,&v,2,2,&mut baseline).unwrap();assert_eq!(a.stored_len(),3);assert!(baseline.reserves>=7);for fault in 1..=baseline.reserves{let mut c=Control{fail:Some(fault),..Default::default()};assert!(matches!(sparse(&i,&j,&v,2,2,&mut c),Err(ScientificErrorV1::Allocation)));assert_eq!(sparse(&i,&j,&v,2,2,&mut Control::default()).unwrap().stored_len(),3)}
 for stop in 1..=baseline.checkpoints{let mut c=Control{stop:Some(stop),..Default::default()};assert!(matches!(sparse(&i,&j,&v,2,2,&mut c),Err(ScientificErrorV1::Cancelled)));}assert_eq!(i.dense_component(0).unwrap().re,2.);
}
#[test]fn zero_axis_outer_loops_still_checkpoint_without_dense_projection(){
 let empty=real(&[0,0],&[]);let a=sparse(&empty,&empty,&empty,0,0,&mut Control::default()).unwrap();let b=real(&[0,257],&[]);let mut c=Control::default();let y=drive(multiply_sparse_dense_ieee_v2(a.csc_view().unwrap(),b.dense_view().unwrap(),64<<20,&mut c)).unwrap();assert_eq!(&*y.axes(),[0,257]);assert_eq!(c.units,257);assert_eq!(c.checkpoints,257);assert_eq!(y.payload_bytes(),0);
 let a=empty.into_dense_v1().unwrap();let b=b.into_dense_v1().unwrap();let mut c=Control::default();let(y,_)=drive(evaluate_scientific_dense_v2(ScientificLeafOperationV1::Binary(BinaryOperatorV1::Multiply),a,Some(b),64<<20,&mut c)).unwrap();assert_eq!(y.shape(),[0,257]);assert_eq!(c.units,257);
}
#[test]fn consumed_real_vector_transpose_needs_no_output_headroom_or_reserve(){let a=real(&[1,257],&[3.;257]);let mut c=Control::default();let(y,d)=drive(evaluate_scientific_dense_v2(ScientificLeafOperationV1::Transpose(true),a.into_dense_v1().unwrap(),None,0,&mut c)).unwrap();assert_eq!(y.shape(),[257,1]);assert!(d.is_none());assert_eq!(c.reserves,0);for i in 0..257{assert_eq!(y.component(i).unwrap(),Complex64V1::real(3.));}}
